UPCOMING_FUNCTION_ENTRIES = tuple(UpcomingFunction(*entry) for entry in _RAW_FUNCTIONS)

UPCOMING_FUNCTIONS = {}
for entry in UPCOMING_FUNCTION_ENTRIES:
    UPCOMING_FUNCTIONS.setdefault(entry.name, []).append(entry)
UPCOMING_FUNCTIONS = {name: tuple(values) for name, values in UPCOMING_FUNCTIONS.items()}

UPCOMING_TOPICS = {}
for entry in UPCOMING_FUNCTION_ENTRIES:
    UPCOMING_TOPICS.setdefault(entry.topic, []).append(entry)
UPCOMING_TOPICS = {topic: tuple(values) for topic, values in UPCOMING_TOPICS.items()}


class UpcomingFunctionNotImplemented(NotImplementedError):
    """Raised when a planned roadmap function is called before implementation."""


def list_upcoming_topics():
    """Return all roadmap topics that have planned function metadata."""

    return tuple(sorted(UPCOMING_TOPICS))


def list_upcoming_functions(topic=None):
    """Return planned function names, optionally filtered by topic."""

    if topic is None:
        return tuple(sorted(UPCOMING_FUNCTIONS))
    return tuple(sorted({entry.name for entry in UPCOMING_TOPICS.get(topic, ())}))


def get_upcoming_function_metadata(name):
    """Return all metadata entries for a planned function name."""

    return UPCOMING_FUNCTIONS.get(name, ())


def is_upcoming_function(name):
    """Return True when name is registered as a planned function."""

    return name in UPCOMING_FUNCTIONS


def _make_upcoming_function(name):
    entries = UPCOMING_FUNCTIONS[name]
    topics = tuple(sorted({entry.topic for entry in entries}))
    signatures = tuple(sorted({entry.signature for entry in entries}))

    def upcoming_function(*args, **kwargs):
        topic_text = ", ".join(topics)
        raise UpcomingFunctionNotImplemented(
            f"{name} is a planned mathfunctionize API for: {topic_text}. "
            "See upcoming.md and professional_function_catalog.md for scope, "
            "then replace this placeholder with a tested implementation."
        )

    upcoming_function.__name__ = name
    upcoming_function.__qualname__ = name
    upcoming_function.__doc__ = (
        f"Planned mathfunctionize function for {', '.join(topics)}. "
        f"Roadmap signatures: {'; '.join(signatures)}. "
        "Raises UpcomingFunctionNotImplemented until implemented."
    )
    return upcoming_function


def install_upcoming_functions(namespace, overwrite=False):
    """Install planned function placeholders into a namespace dictionary."""

    installed = []
    for name in sorted(UPCOMING_FUNCTIONS):
        if overwrite or name not in namespace:
            namespace[name] = _make_upcoming_function(name)
            installed.append(name)
    return tuple(installed)


_INSTALLED_NAMES = install_upcoming_functions(globals(), overwrite=False)

__all__ = (
    'UpcomingFunction',
    'UpcomingFunctionNotImplemented',
    'UPCOMING_FUNCTION_ENTRIES',
    'UPCOMING_FUNCTIONS',
    'UPCOMING_TOPICS',
    'get_upcoming_function_metadata',
    'install_upcoming_functions',
    'is_upcoming_function',
    'list_upcoming_functions',
    'list_upcoming_topics',
) + _INSTALLED_NAMES
